    public static final int EVENT_KILL = 5;
    public static final int EVENT_LOST = 6;

    private long timestampMicros;
    private long jobId;
    private int eventType;

    public JobEvent() {}

    public JobEvent(long timestampMicros, long jobId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getEventType() {
        return eventType;
    }

    public boolean isTerminal() {
        return eventType == EVENT_FINISH || eventType == EVENT_FAIL || eventType == EVENT_KILL || eventType == EVENT_LOST;
    }

    public static JobEvent fromCsvLine(String line) {
        // job_events schema (v2.1):
        // 0 time, 1 missing info, 2 job ID, 3 event type, ...
        String[] f = line.split(",", -1);
        if (f.length < 4) {
            return null;
        }
        long ts = parseLongRequired(f[0]);
        long jobId = parseLongRequired(f[2]);
        int eventType = (int) parseLongRequired(f[3]);
        return new JobEvent(ts, jobId, eventType);
    }

    private static long parseLongRequired(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Missing required long field");
        }
        return Long.parseLong(s);
    }
}
