", "new_str": "package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.RichSourceFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);

        // Session size in seconds. Default 600s = 10 minutes.
        final int sesssize = params.getInt("sesssize", 600);
        final long sessionGapMs = sesssize * 1000L;

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new GzipTaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis())
                );

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new GzipJobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((e, ts) -> e.getTimestampMillis())
                );

        KeyedStream<TaskEvent, Long> submits = tasks
                .filter(TaskEvent::isSubmit)
                .keyBy(TaskEvent::getJobId);

        KeyedStream<JobEvent, Long> terminalJobs = jobs
                .filter(JobEvent::isTerminal)
                .keyBy(JobEvent::getJobId);

        DataStream<Tuple2<Long, Long>> longestStagePerJob = submits
                .connect(terminalJobs)
                .process(new LongestStageOnJobFinish(sessionGapMs));

        DataStream<String> formatted = longestStagePerJob
                .map((MapFunction<Tuple2<Long, Long>, String>) value -> "(" + value.f0 + "," + value.f1 + ")");

        formatted
                .addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static final class LongestStageOnJobFinish extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Long>> {

        private final long sessionGapMs;

        private transient ValueState<Long> lastSubmitTsMs;
        private transient ValueState<Long> currentStageCount;
        private transient ValueState<Long> maxStageCount;
        private transient ValueState<Long> stageCloseTimerTs;
        private transient ValueState<Boolean> jobTerminalSeen;
        private transient ValueState<Boolean> emitted;

        private LongestStageOnJobFinish(long sessionGapMs) {
            this.sessionGapMs = sessionGapMs;
        }

        @Override
        public void open(Configuration parameters) {
            lastSubmitTsMs = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTsMs", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Long.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            stageCloseTimerTs = getRuntimeContext().getState(new ValueStateDescriptor<>("stageCloseTimerTs", Long.class));
            jobTerminalSeen = getRuntimeContext().getState(new ValueStateDescriptor<>("jobTerminalSeen", Boolean.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long ts = value.getTimestampMillis();

            Long cur = currentStageCount.value();
            if (cur == null) {
                cur = 0L;
            }
            cur += 1L;
            currentStageCount.update(cur);

            Long prevLast = lastSubmitTsMs.value();
            if (prevLast == null || ts > prevLast) {
                lastSubmitTsMs.update(ts);
            }

            Long oldTimer = stageCloseTimerTs.value();
            if (oldTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldTimer);
            }
            long newTimer = (lastSubmitTsMs.value() != null ? lastSubmitTsMs.value() : ts) + sessionGapMs;
            ctx.timerService().registerEventTimeTimer(newTimer);
            stageCloseTimerTs.update(newTimer);
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            jobTerminalSeen.update(true);

            Long cur = currentStageCount.value();
            if (cur == null || cur == 0L) {
                long max = valueOrZero(maxStageCount.value());
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                clearAll(ctx);
                return;
            }

            // There is an active stage; wait for inactivity-gap timer to close it.
            Long last = lastSubmitTsMs.value();
            if (last != null && stageCloseTimerTs.value() == null) {
                long t = last + sessionGapMs;
                ctx.timerService().registerEventTimeTimer(t);
                stageCloseTimerTs.update(t);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            // Close current stage (if any).
            long cur = valueOrZero(currentStageCount.value());
            long max = valueOrZero(maxStageCount.value());
            if (cur > 0) {
                max = Math.max(max, cur);
                maxStageCount.update(max);
            }

            currentStageCount.clear();
            lastSubmitTsMs.clear();
            stageCloseTimerTs.clear();

            if (Boolean.TRUE.equals(jobTerminalSeen.value())) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                clearAll(ctx);
            }
        }

        private static long valueOrZero(Long v) {
            return v == null ? 0L : v;
        }

        private void clearAll(Context ctx) throws Exception {
            Long oldTimer = stageCloseTimerTs.value();
            if (oldTimer != null) {
                ctx.timerService().deleteEventTimeTimer(oldTimer);
            }
            currentStageCount.clear();
            lastSubmitTsMs.clear();
            maxStageCount.clear();
            stageCloseTimerTs.clear();
            jobTerminalSeen.clear();
            emitted.update(true);
        }
    }

    private static final class GzipTaskEventSource extends RichSourceFunction<TaskEvent> {

        private final String inputPath;
        private volatile boolean running = true;

        private GzipTaskEventSource(String inputPath) {
            this.inputPath = inputPath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(
                    new GZIPInputStream(new java.io.FileInputStream(inputPath)), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    TaskEvent e = TaskEvent.fromCsvLine(line);
                    if (e == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(e);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class GzipJobEventSource extends RichSourceFunction<JobEvent> {

        private final String inputPath;
        private volatile boolean running = true;

        private GzipJobEventSource(String inputPath) {
            this.inputPath = inputPath;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(
                    new GZIPInputStream(new java.io.FileInputStream(inputPath)), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    JobEvent e = JobEvent.fromCsvLine(line);
                    if (e == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collect(e);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class LocalFileSink extends RichSinkFunction<String> {

        private final String outputPath;
        private transient BufferedWriter writer;

        private LocalFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            super.open(parameters);
            writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(outputPath, false), StandardCharsets.UTF_8));
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
            super.close();
        }
    }
}
