        private final long sessionGapMicros;

        private transient ValueState<Long> lastSubmitTsMicros;
        private transient ValueState<Long> currentStageCount;
        private transient ValueState<Long> maxStageCount;
        private transient ValueState<Boolean> terminalSeen;
        private transient ValueState<Boolean> endTimerSet;
        private transient ValueState<Boolean> emitted;

        private LongestStageOnJobFinish(long sessionGapMicros) {
            this.sessionGapMicros = sessionGapMicros;
        }

        @Override
        public void open(Configuration parameters) {
            lastSubmitTsMicros = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTsMicros", Long.class));
            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Long.class));
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Long.class));
            terminalSeen = getRuntimeContext().getState(new ValueStateDescriptor<>("terminalSeen", Boolean.class));
            endTimerSet = getRuntimeContext().getState(new ValueStateDescriptor<>("endTimerSet", Boolean.class));
            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            long ts = value.getTimestampMicros();

            Long last = lastSubmitTsMicros.value();
            long cur = valueOrZero(currentStageCount.value());
            long max = valueOrZero(maxStageCount.value());

            // Stage boundary: more than 10 minutes without a SUBMIT event for this job.
            if (last != null && ts >= last && ts - last > sessionGapMicros && cur > 0L) {
                maxStageCount.update(Math.max(max, cur));
                cur = 0L;
            }

            cur += 1L;
            currentStageCount.update(cur);

            if (last == null || ts >= last) {
                lastSubmitTsMicros.update(ts);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value())) {
                return;
            }

            terminalSeen.update(true);
            if (!Boolean.TRUE.equals(endTimerSet.value())) {
                // Emit only once all bounded inputs are finished.
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE);
                endTimerSet.update(true);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (Boolean.TRUE.equals(emitted.value()) || !Boolean.TRUE.equals(terminalSeen.value())) {
                return;
            }
            if (timestamp != Long.MAX_VALUE) {
                return;
            }

            long cur = valueOrZero(currentStageCount.value());
            long max = Math.max(valueOrZero(maxStageCount.value()), cur);
            out.collect(Tuple2.of(ctx.getCurrentKey(), max));
            clearAll(ctx);
        }

        private static long valueOrZero(Long v) {
            return v == null ? 0L : v;
        }

        private void clearAll(Context ctx) throws Exception {
            if (Boolean.TRUE.equals(endTimerSet.value())) {
                ctx.timerService().deleteEventTimeTimer(Long.MAX_VALUE);
            }
            lastSubmitTsMicros.clear();
            currentStageCount.clear();
            maxStageCount.clear();
            terminalSeen.clear();
            endTimerSet.clear();
            emitted.update(true);
        }
    }
